package com.benbenyu.btquicklaunch;
import java.util.concurrent.*;
final class NetworkCheck {
 static final ThreadPoolExecutor probes=new ThreadPoolExecutor(2,2,0L,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<Runnable>(2),new ThreadPoolExecutor.AbortPolicy());
 static boolean reachable(){CompletionService<Boolean> results=new ExecutorCompletionService<>(probes);java.util.ArrayList<Future<Boolean>> pending=new java.util.ArrayList<>();try{for(String url:new String[]{"https://www.google.com/generate_204","https://chatgpt.com/"})pending.add(results.submit(()->probe(url)));long until=android.os.SystemClock.elapsedRealtime()+4500;for(int i=0;i<2;i++){long left=until-android.os.SystemClock.elapsedRealtime();if(left<=0)break;Future<Boolean> result=results.poll(left,TimeUnit.MILLISECONDS);if(result!=null&&result.get())return true;}}catch(Exception ex){AppLog.write("NET_CHECK bounded failure="+ex.getClass().getSimpleName(),null);}finally{for(Future<Boolean> task:pending)task.cancel(true);}return false;}
 static boolean probe(String url){javax.net.ssl.HttpsURLConnection c=null;try{c=(javax.net.ssl.HttpsURLConnection)new java.net.URL(url).openConnection();c.setConnectTimeout(2000);c.setReadTimeout(2000);c.setInstanceFollowRedirects(false);c.setRequestMethod("HEAD");c.setUseCaches(false);int status=c.getResponseCode();AppLog.write("NET_CHECK host="+new java.net.URL(url).getHost()+" status="+status,null);return url.contains("google.com")?status==204:(status==200||status==403);}catch(Exception e){AppLog.write("NET_CHECK failed="+e.getClass().getSimpleName(),null);return false;}finally{if(c!=null)c.disconnect();}}
}
